DELIMITER ;

DROP PROCEDURE IF EXISTS reborn_wd95_testpoints;
DELIMITER $$
CREATE PROCEDURE reborn_wd95_testpoints(IN p_guid INT UNSIGNED,IN p_account INT UNSIGNED,IN p_revision INT UNSIGNED,IN p_ae INT UNSIGNED,IN p_te INT UNSIGNED)
SQL SECURITY INVOKER
proc:BEGIN
 DECLARE v_account BIGINT DEFAULT -1;
 DECLARE v_class INT DEFAULT 0;
 DECLARE v_race INT DEFAULT 0;
 DECLARE v_revision BIGINT DEFAULT -1;
 DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK;SELECT 0 AS result;END;
 IF p_ae>100 OR p_te>100 THEN SELECT 0 AS result;LEAVE proc;END IF;
 START TRANSACTION;
 SELECT account,class,race INTO v_account,v_class,v_race FROM characters WHERE guid=p_guid FOR UPDATE;
 IF v_account<>p_account OR v_class<>13 OR v_race<>1 THEN ROLLBACK;SELECT 0 AS result;LEAVE proc;END IF;
 SELECT revision INTO v_revision FROM reborn_wd5a_builds WHERE guid=p_guid FOR UPDATE;
 IF v_revision<0 OR v_revision<>p_revision OR v_revision>=2000000000 THEN ROLLBACK;SELECT 2 AS result;LEAVE proc;END IF;
 IF NOT EXISTS(SELECT 1 FROM reborn_wd67_members WHERE guid=p_guid AND enabled=1) THEN ROLLBACK;SELECT 0 AS result;LEAVE proc;END IF;
 -- Every saved slot is protected, including an inactive slot after a level reduction.
 IF EXISTS(SELECT slot FROM reborn_wd67_nodes WHERE guid=p_guid GROUP BY slot
 HAVING SUM(CASE WHEN node_id IN(29744,6054,6047,7092,29309,29301,7088,30147,4132,7033,6051,6048,30891,6030,6381,12048,11323,31118,12264,6042,9347,29306,6031,6525,12525) THEN node_rank ELSE 0 END)>36+p_ae
 OR SUM(CASE WHEN node_id NOT IN(29744,6054,6047,7092,29309,29301,7088,30147,4132,7033,6051,6048,30891,6030,6381,12048,11323,31118,12264,6042,9347,29306,6031,6525,12525,4005,12645,12646,4004,4533,11532,4532,11133,9311,4715) THEN node_rank ELSE 0 END)>35+p_te)
 THEN ROLLBACK;SELECT 4 AS result;LEAVE proc;END IF;
 INSERT INTO reborn_wd95_test_points(guid,account,extra_ae,extra_te) VALUES(p_guid,p_account,p_ae,p_te)
 ON DUPLICATE KEY UPDATE account=p_account,extra_ae=p_ae,extra_te=p_te;
 UPDATE reborn_wd5a_builds SET revision=revision+1 WHERE guid=p_guid;
 COMMIT;SELECT 1 AS result;
END$$
DELIMITER ;
